-- đã chạy
-- VetMate: ca khám và bác sĩ tham gia, theo Các bảng.docx.
-- Điều kiện: database/01 đến 09 đã được triển khai và kiểm tra.
-- Chỉ tạo cấu trúc, không seed dữ liệu, không tự chuyển trạng thái booking.
-- IF NOT EXISTS không thay thế migration nếu bảng đã có cấu trúc khác.
BEGIN;

CREATE TABLE IF NOT EXISTS medical."medicalVisits" (
    "visitID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "appointmentID" BIGINT UNIQUE REFERENCES booking."appointments"("appointmentID") ON DELETE RESTRICT,
    "petID" BIGINT NOT NULL REFERENCES medical."pets"("petID") ON DELETE RESTRICT,
    "visitDate" DATE NOT NULL,
    "visitCode" VARCHAR(30) NOT NULL UNIQUE CHECK (length(trim("visitCode")) > 0),
    "chiefComplaint" TEXT NOT NULL CHECK (length(trim("chiefComplaint")) > 0),
    "symptoms" TEXT,
    "weightKg" NUMERIC(8,3) CHECK ("weightKg" > 0),
    "temperatureC" NUMERIC(5,2) CHECK ("temperatureC" > 0),
    "heartRate" INTEGER CHECK ("heartRate" > 0),
    "respiratoryRate" INTEGER CHECK ("respiratoryRate" > 0),
    -- NULL được phép khi mới nhận lượt, chưa khám; kiểm tra trước khi chốt ở backend.
    "clinicalExamination" TEXT,
    "preliminaryDiagnosis" TEXT,
    "finalDiagnosis" TEXT,
    "treatmentPlan" TEXT,
    "careInstructions" TEXT,
    "status" VARCHAR(20) NOT NULL DEFAULT 'DRAFT'
        CHECK ("status" IN ('DRAFT', 'COMPLETED')),
    "startedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "completedAt" TIMESTAMPTZ,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "ckMedicalVisitCompletion" CHECK (
        ("status" = 'DRAFT' AND "completedAt" IS NULL)
        OR ("status" = 'COMPLETED' AND "completedAt" IS NOT NULL AND "completedAt" >= "startedAt")
    )
);

CREATE TABLE IF NOT EXISTS medical."visitVeterinarians" (
    "visitID" BIGINT NOT NULL REFERENCES medical."medicalVisits"("visitID") ON DELETE RESTRICT,
    "veterinarianID" BIGINT NOT NULL REFERENCES clinic."veterinarians"("veterinarianID") ON DELETE RESTRICT,
    "participationRole" VARCHAR(20) NOT NULL
        CHECK ("participationRole" IN ('PRIMARY', 'ASSISTING', 'CONSULTING', 'PROCEDURE')),
    "assignedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "note" TEXT,
    PRIMARY KEY ("visitID", "veterinarianID")
);
-- Tối đa một bác sĩ chính; backend bảo đảm luôn có bác sĩ chính khi nhận/chốt ca.
CREATE UNIQUE INDEX IF NOT EXISTS "uqVisitPrimaryVeterinarian"
    ON medical."visitVeterinarians" ("visitID") WHERE "participationRole" = 'PRIMARY';
CREATE INDEX IF NOT EXISTS "idxVisitVeterinariansVeterinarian"
    ON medical."visitVeterinarians" ("veterinarianID", "visitID");
CREATE INDEX IF NOT EXISTS "idxMedicalVisitsPetDate"
    ON medical."medicalVisits" ("petID", "visitDate" DESC);
CREATE INDEX IF NOT EXISTS "idxMedicalVisitsDateStatus"
    ON medical."medicalVisits" ("visitDate", "status");

CREATE TABLE IF NOT EXISTS medical."petWeightHistory" (
    "weightID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "petID" BIGINT NOT NULL REFERENCES medical."pets"("petID") ON DELETE RESTRICT,
    "weightKg" NUMERIC(8,3) NOT NULL CHECK ("weightKg" > 0),
    "measuredAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "recordedByStaffID" BIGINT REFERENCES clinic."clinicStaff"("staffID") ON DELETE RESTRICT,
    "note" TEXT
);
CREATE INDEX IF NOT EXISTS "idxPetWeightHistoryPetMeasured"
    ON medical."petWeightHistory" ("petID", "measuredAt" DESC);

CREATE OR REPLACE FUNCTION medical."touchVisitUpdatedAt"()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    NEW."updatedAt" = now();
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS "trgMedicalVisitUpdatedAt" ON medical."medicalVisits";
CREATE TRIGGER "trgMedicalVisitUpdatedAt"
BEFORE UPDATE ON medical."medicalVisits"
FOR EACH ROW EXECUTE FUNCTION medical."touchVisitUpdatedAt"();

COMMENT ON TABLE medical."medicalVisits" IS
    'Ca khám và bệnh án; DRAFT là chưa chốt. Quyền sửa, dữ liệu chốt và đồng bộ booking do backend kiểm tra trong transaction.';
COMMENT ON COLUMN medical."medicalVisits"."appointmentID" IS
    'Nullable theo thiết kế; khi có lịch hẹn phải cùng petID. Backend kiểm tra và khóa lịch khi tạo ca.';
COMMENT ON TABLE medical."petWeightHistory" IS
    'Ghi nhận lần đo; không tự thêm mỗi lần lưu bệnh án. Backend tránh ghi lặp cùng thao tác đo.';
COMMIT;
